-- RESIDENTIAL QUALIFICATION measurement. Read-only. The CASE is GENERATED by
-- scripts/residential-qualify-sql.mjs from lib/residential-qualify.js own exported vocabulary,
-- so the measured rule and the shipped rule are the same rule (parity pinned by
-- test/residential-qualify-sql-parity.test.mjs).
--
-- SHAPE MATTERS: a cross-join-lateral over the 762k membership keys forced that many nested
-- loops and timed out twice at the 120s Management-API limit. A hash join of the membership
-- keys against ONE app_projects scan is the shape that completes. Do not "optimise" it back.
-- Duplicate app_projects rows per source_key carry the same type_raw and name, so the verdict
-- is constant per object and count(distinct source_key) is exact without a dedupe pass.
-- PART 2 — ZIP-level: the 12,722-page reconciliation.
with m as (select mm.zcta5, mm.source_key from geo.zip_authoritative_membership mm
           join geo.maps_zip_geography_status s on s.zip = mm.zcta5 and s.status='boundary_complete'),
k as (select distinct source_key from m),
n as (select a.source_key, a.type, (' ' || btrim(regexp_replace(lower(coalesce(type_raw,'')), '[^a-z0-9]+', ' ', 'g')) || ' ') as tr, (' ' || btrim(regexp_replace(lower(coalesce(name,'')), '[^a-z0-9]+', ' ', 'g')) || ' ') as nm from public.app_projects a join k on k.source_key = a.source_key
      where a.record_kind='development' and a.type='Residential'),
v as (select distinct source_key, case when (tr || nm) ~ ' (subdivision|resubdivision|subdivisions|plat|plats|replat|preliminary plat|final plat|site plan|site development plan|sitedevelopment|planned development|planned unit development|master plan|land development) ' then 'DEVELOPMENT' when nm ~ '^ (hvac|electric|electrical|plumbing|plumb|mechanical|gas piping|gas appliances|venting|boiler|furnace|water heater|photovoltaic|solar|trade|trades|ele|mec|plu|sprinkler|irrigation|low voltage|alter|alters|alteration|alterations|remodel|remodeling|renovation|renovations|repair|repairs|replace|replacing|replacement|reroof|re roof|roofing|roof|siding|window|windows|deck|decks|porch|porches|fence|fencing|pool|pools|spa|shed|carport|garage|accessory|maintenance|demolition|demo|tear off|tear down|teardown|interior|finish basement|basement finish|addition|additions|relocation|move|sign|signs|fire damage|retaining wall|driveway|patio|awning|generator|ev charger|antenna|alt|air conditioning|ductwork|tree|trees) ' then 'ROUTINE' when tr ~ '^ (new construction|new residential|new single family|new multi family|new multifamily|new apartment|new home|new homes|new house|new dwelling|new building|new bldg|new sfr|new sfd|residential new|construction residential|residential construction|site dev|sfd devel|ground up) ' or nm ~ '^ (new construction|new residential|new single family|new multi family|new multifamily|new apartment|new home|new homes|new house|new dwelling|new building|new bldg|new sfr|new sfd|residential new|construction residential|residential construction|site dev|sfd devel|ground up) ' then 'DEVELOPMENT' when tr ~ '^ (new|nb|dsp) ' and tr ~ ' (construction|home|homes|house|dwelling|dwellings|residence|residences|residential|duplex|apartment|apartments|townhome|townhomes|townhouse|condo|condominium|sfr|sfd|building|bldg|units|unit) ' then 'DEVELOPMENT' when nm ~ '^ (new|nb|dsp) ' and nm ~ ' (construction|home|homes|house|dwelling|dwellings|residence|residences|residential|duplex|apartment|apartments|townhome|townhomes|townhouse|condo|condominium|sfr|sfd|building|bldg|units|unit) ' then 'DEVELOPMENT' when (tr || nm) ~ ' (hvac|electric|electrical|plumbing|plumb|mechanical|gas piping|gas appliances|venting|boiler|furnace|water heater|photovoltaic|solar|trade|trades|ele|mec|plu|sprinkler|irrigation|low voltage|alter|alters|alteration|alterations|remodel|remodeling|renovation|renovations|repair|repairs|replace|replacing|replacement|reroof|re roof|roofing|roof|siding|window|windows|deck|decks|porch|porches|fence|fencing|pool|pools|spa|shed|carport|garage|accessory|maintenance|demolition|demo|tear off|tear down|teardown|interior|finish basement|basement finish|addition|additions|relocation|move|sign|signs|fire damage|retaining wall|driveway|patio|awning|generator|ev charger|antenna|alt|air conditioning|ductwork|tree|trees) ' then 'ROUTINE' when (registry_id = 'denton-county-dev-permits' and tr in (' house ', ' duplex ', ' mobile home ')) or (registry_id = 'dekalb-county-building-permits' and tr in (' new homes ')) then 'DEVELOPMENT' else 'UNRESOLVED' end as verdict from n),
z as (select m.zcta5, v.verdict from m join v on v.source_key = m.source_key)
select 'P_control_canonical_zips' as metric, (select count(*)::text from public.canonical_zip_registry) as value
union all select 'Q_control_zips_boundary_complete', (select count(*)::text from geo.maps_zip_geography_status where status='boundary_complete')
union all select 'R_zips_with_any_development_object', (select count(distinct zcta5)::text from m)
union all select 'S_zips_with_residential_before', count(distinct zcta5)::text from z
union all select 'T_zips_with_residential_after', count(distinct zcta5)::text from z where verdict='DEVELOPMENT'
union all select 'U_zips_losing_residential_entirely',
  (select count(*)::text from (select zcta5 from z group by zcta5 having count(*) filter (where verdict='DEVELOPMENT') = 0) q)
order by 1;
